-- Chat conversation titling (see src/server/chat/title.ts): tracks WHERE a
-- conversation's title came from so auto-titling never clobbers a manual
-- rename. Values:
--   'seed' — the message.slice(0,60) fallback written by resolveConversation
--            in chat.ts when a conversation is first created
--   'auto' — LLM-generated by title.ts's titleConversation, after assistant
--            turns 1, 4, and 10
--   'user' — renamed via PATCH /api/chat/conversations/:id; freezes the
--            title forever (titleConversation's UPDATE is guarded
--            WHERE title_source <> 'user')
ALTER TABLE conversations ADD COLUMN IF NOT EXISTS title_source TEXT NOT NULL DEFAULT 'seed';
